function go(v){view=v;$('#detail').classList.add('hidden');selected=null;document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===v));desk.visible=v!=='scene';investigation.visible=v==='scene';if(v==='scene'){camGoal.set(8,10,12);lookGoal.set(0,2.2,0);setPlace(place)}else{camGoal.set(v==='archive'?13:8,11,v==='archive'?17:19);lookGoal.set(v==='archive'?-1:0,1.5,0);render()}tone(240)}
