function bind(){ $('#start')?.addEventListener('click',()=>go('scene'));document.querySelectorAll('[data-place]').forEach(b=>b.onclick=()=>{tone();setPlace(+b.dataset.place)});document.querySelectorAll('[data-clue]').forEach(b=>b.onclick=()=>showClue(b.dataset.clue));document.querySelectorAll('[data-person]').forEach(b=>b.onclick=()=>interview(+b.dataset.person));}
function showClue(id){const c=clues.find(c=>c.id===id);$('#detail').classList.remove('hidden');$('#detail').innerHTML=`<button class="close" aria-label="Close">×</button><span class="eyebrow">EVIDENCE / ${c.kind}</span><h2>${c.name}</h2><p>${c.text}</p><button class="primary" id="collect">${state.found.includes(id)?'Already in your case file':'Pin to evidence board'} <span>↗</span></button>`;$('#detail .close').onclick=()=>$('#detail').classList.add('hidden');$('#collect').onclick=()=>{if(!state.found.includes(id)){state.found.push(id);save();tone(520);toast('Evidence secured: '+c.name)}$('#detail').classList.add('hidden');render()};}
function interview(i){const c=clues.find(c=>c.interview===i);if(c){showClue(c.id);return}$('#detail').classList.remove('hidden');$('#detail').innerHTML=`<button class="close" aria-label="Close">×</button><span class="eyebrow">WITNESS INTERVIEW</span><h2>${suspects[i]}</h2><p>${i===1?'“I was furious with Edmund, yes. But I was at the station when he died. Ask the clerk. My ticket has the time on it.”':'“Clara and I were in the kitchen all evening. Supper doesn’t prepare itself. The guests can tell you when we served.”'}</p><p><small>Look for independent evidence to check this account.</small></p>`;$('#detail .close').onclick=()=>$('#detail').classList.add('hidden');tone(280);}
function renderBoard(){ui.innerHTML=`<section class="page-top"><div><span class="eyebrow">FOLLOW THE THREAD</span><h1>The evidence room</h1><p>${state.found.length} of 14 clues recovered · ${state.links.length} connections made</p></div><div class="chips"><button class="chip" id="timeline">${timeline?'Evidence board':'Timeline'}</button><button class="chip" id="accuse">Make an accusation ↗</button></div></section><section class="workspace"><div class="board-tools"><p>${timeline?'Reconstruct the evening from the records you have recovered.':'Select two cards to connect them. Drag cards to arrange your board.'}</p><div class="chips"><button class="chip" id="inspect">◎ Inspect case</button><button class="chip" id="break">✂ Break a clue</button></div></div>${timeline?timelineHTML():`<div class="evidence-grid" id="cards">${state.found.map(id=>{const c=clues.find(c=>c.id===id);return `<button class="evidence-card" data-card="${id}"><small>${c.kind} / ${id}</small><strong>${c.name}</strong><p>${c.text}</p></button>`}).join('')}<svg class="board-svg" id="strings"></svg></div>`}${!state.found.length?'<p class="empty">Your board is waiting. Search the study and interview the suspects to collect your first clues.</p><button class="primary" id="search">Return to the study ↗</button>':''}<div class="link-list">${state.links.map((l,i)=>`<button data-link="${i}" title="Remove connection">${l.map(id=>clues.find(c=>c.id===id).name).join(' ↔ ')} ×</button>`).join('')}</div><div id="report"></div></section>`;
 $('#timeline').onclick=()=>{timeline=!timeline;render()};$('#accuse').onclick=()=>go('accuse');$('#search')?.addEventListener('click',()=>go('scene'));$('#inspect').onclick=()=>inspect(false);$('#break').onclick=()=>inspect(true);document.querySelectorAll('[data-link]').forEach(b=>b.onclick=()=>{state.links.splice(+b.dataset.link,1);save();render()});
 document.querySelectorAll('[data-card]').forEach(el=>{let start,moved=false;el.onpointerdown=e=>{start={x:e.clientX,y:e.clientY};moved=false;el.setPointerCapture(e.pointerId)};el.onpointermove=e=>{if(!start)return;const dx=e.clientX-start.x,dy=e.clientY-start.y;if(Math.abs(dx)+Math.abs(dy)>8){moved=true;el.style.transform=`translate(${dx}px,${dy}px)`;drawLinks()}};el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();moved=false;el.onpointerup()}};el.onpointerup=()=>{start=null;if(moved){drawLinks();return}const id=el.dataset.card;if(!selected){selected=id;el.classList.add('selected');return}if(selected!==id){if(!state.links.some(l=>l.includes(id)&&l.includes(selected))){state.links.push([selected,id]);save();if([id,selected].includes('statement')&&[id,selected].includes('log'))toast('CONFLICT — Evelyn’s statement contradicts the gatekeeper’s log.');else toast('Connection added to your theory.');tone(430)}}selected=null;render()};});requestAnimationFrame(drawLinks);}
function drawLinks(){const svg=$('#strings'),cards=$('#cards');if(!svg||!cards)return;const rect=cards.getBoundingClientRect();svg.innerHTML=state.links.map(([a,b])=>{const ea=document.querySelector(`[data-card="${a}"]`),eb=document.querySelector(`[data-card="${b}"]`);if(!ea||!eb)return '';const ra=ea.getBoundingClientRect(),rb=eb.getBoundingClientRect();return `<line x1="${ra.x+ra.width/2-rect.x}" y1="${ra.y+10-rect.y}" x2="${rb.x+rb.width/2-rect.x}" y2="${rb.y+10-rect.y}"/>`}).join('');}
function timelineHTML(){const events=[['will','08:30','Edmund changes his will.'],['key','20:55','Evelyn collects the study key.'],['witness','21:05','Clara sees Evelyn carrying the nightcap.'],['log','21:12','Evelyn enters the study passage.'],['receipt','21:18','Arthur is at the railway station.'],['clock','21:20','Edmund’s watch stops.'],['schedule','21:30','Supper service ends.']];return `<div class="timeline">${events.filter(e=>state.found.includes(e[0])).map(e=>`<article><b>${e[1]}</b><p>${e[2]}</p></article>`).join('')||'<p class="empty">Collect timestamped evidence to reconstruct the evening.</p>'}</div>`;}
function inspect(broken){const c=makeCase();if(broken)c.nodes=c.nodes.filter(n=>n.id!=='glass');const r=verify(c),el=$('#report');el.className='report scanning '+(r.ok?'':'error');el.innerHTML=`<span class="stamp">${r.ok?'VERIFIED':'REJECTED'}</span><h3>${r.ok?'This mystery holds together.':'One missing clue. A broken case.'}</h3><p>${r.ok?`Reachability ✓ · Prerequisites ✓ · No circular dependencies ✓<br>Evidence justification ✓ · Unique solution ✓ · Contradiction records ✓<br>${r.validRoutes.length} complete solution routes. Shortest route: ${r.shortest} clues. ${r.reachable}/${r.total} clues reachable.<br>Certificate / seed 1042 / deterministic graph verification`:'Demonstration: “The last drink” was removed from a temporary copy of the case.<br>'+r.errors.join('<br>')+'<br>Your collected evidence is preserved.'}</p>${r.ok?'<button class="chip" id="reveal">Reveal solution routes (spoilers)</button>':'<button class="chip" id="restore">Restore clue & recheck</button>'}`;$('#reveal')?.addEventListener('click',()=>{el.innerHTML+='<p>'+routes.map((r,i)=>`Route ${i+1}: ${r.map(id=>clues.find(c=>c.id===id).name).join(' → ')} → Evelyn Marsh`).join('<br>')+'</p>'});$('#restore')?.addEventListener('click',()=>inspect(false));tone(r.ok?600:140);el.scrollIntoView({behavior:'smooth',block:'nearest'});}
function renderAccuse(){ui.innerHTML=`<section class="page-top"><div><span class="eyebrow">THE FINAL ACCOUNT</span><h1>Make your case.</h1><p>Choose a suspect. Attach evidence for motive, means and opportunity.</p></div><button class="chip" id="back">← Evidence room</button></section><section class="workspace"><div class="accuse-grid">${suspects.map((s,i)=>`<button class="suspect ${accused===s?'selected':''}" data-suspect="${i}"><small>SUSPECT 0${i+1}</small><strong>${s}</strong><small>${['THE HEIRESS','THE CREDITOR','THE HOUSEKEEPER','THE GROUNDSKEEPER'][i]}</small></button>`).join('')}</div><div class="chips">${state.found.map(id=>`<label class="chip"><input type="checkbox" value="${id}"> ${clues.find(c=>c.id===id).name}</label>`).join('')||'<p class="empty">You need to collect evidence before submitting an accusation.</p>'}</div><br><button class="primary" id="submit">Submit accusation <span>↗</span></button><div id="verdict" role="status"></div></section>`;$('#back').onclick=()=>go('board');document.querySelectorAll('[data-suspect]').forEach(b=>b.onclick=()=>{accused=suspects[+b.dataset.suspect];document.querySelectorAll('[data-suspect]').forEach(el=>el.classList.toggle('selected',el===b))});$('#submit').onclick=()=>{if(!accused){toast('Choose a suspect first.');return}const r=accuse(accused,[...document.querySelectorAll('input:checked')].map(x=>x.value));$('#verdict').className='report '+(r.ok?'':'error');$('#verdict').innerHTML=`<span class="stamp">${r.ok?'CASE CLOSED':'NOT PROVEN'}</span><p>${r.text}</p>`;if(r.ok){state.solved=true;save()}tone(r.ok?700:160)};}
function renderLab(){ui.innerHTML=`<section class="page-top"><div><span class="eyebrow">TRUST, BUT VERIFY</span><h1>Inside the case engine.</h1><p>100 seeded evidence graphs. Every dependency checked before a case can ship.</p></div><div class="chips"><button class="chip ${!labMode?'selected':''}" id="safe">Constrained generator</button><button class="chip ${labMode?'selected':''}" id="naive">Naive generator</button></div></section><section class="workspace"><div class="board-tools"><p>Seed range 1000–1099 · Deterministic graph stress test</p><button class="primary" id="run">Run 100 cases <span>↗</span></button></div><div id="lab-output"><p class="empty">The constrained generator preserves valid evidence routes. The naive generator introduces random prerequisites. Run the test to see which cases survive.</p></div><div id="seed-report"></div></section>`;$('#safe').onclick=()=>{labMode=false;labResults=[];render()};$('#naive').onclick=()=>{labMode=true;labResults=[];render()};$('#run').onclick=runLab;if(labResults.length)showLab();}
let worker;function runLab(){ $('#run').disabled=true;$('#run').textContent='Checking graphs…';worker??=new Worker('worker.js',{type:'module'});worker.onmessage=e=>{labResults=e.data;showLab();$('#run').disabled=false;$('#run').innerHTML='Run 100 cases <span>↗</span>';tone(500)};worker.onerror=()=>{toast('The case worker could not start. Reload to try again.');$('#run').disabled=false};worker.postMessage({naive:labMode});}
function showLab(){const ok=labResults.filter(r=>r.result.ok).length;$('#lab-output').innerHTML=`<div class="metrics"><div><strong>100</strong><span>CASES GENERATED</span></div><div><strong>${ok}</strong><span>VERIFIED</span></div><div><strong>${100-ok}</strong><span>REJECTED BEFORE PLAY</span></div></div><p class="empty">${labMode?'Random prerequisites can make evidence unreachable. Rejected folders show the exact fault.':'All 100 graphs preserve a unique, justified solution. These are structural test cases; the Lantern House is the authored playable case.'}</p><div class="lab-grid">${labResults.map((r,i)=>`<button class="seed ${r.result.ok?'':'bad'}" data-seed="${i}" aria-label="Inspect seed ${r.seed}, ${r.result.ok?'verified':'rejected'}">${r.seed}</button>`).join('')}</div>`;document.querySelectorAll('[data-seed]').forEach(b=>b.onclick=()=>{const r=labResults[+b.dataset.seed];$('#seed-report').className='report '+(r.result.ok?'':'error');$('#seed-report').innerHTML=`<h3>Seed ${r.seed} / ${r.result.ok?'VERIFIED':'REJECTED'}</h3><p>${r.result.ok?`${r.result.validRoutes.length} valid routes · shortest route ${r.result.shortest} clues · ${r.result.reachable} reachable clues`:r.result.errors.join('<br>')}</p>`})}
$('#sound').onclick=()=>{sound=!sound;$('#sound').textContent=sound?'Sound on':'Sound off';tone();$('#introvideo').muted=!sound};
const video=$('#introvideo');function endIntro(){video.pause();$('#intro').classList.add('hidden');go('archive')}$('#enter').onclick=()=>{$('#intro').classList.add('playing');video.muted=!sound;video.play().catch(()=>{toast('Video playback unavailable. Entering the archive.');endIntro()})};$('#skip').onclick=endIntro;video.onended=endIntro;video.onerror=()=>{if($('#intro').classList.contains('playing'))endIntro()};$('#replay').onclick=()=>{$('#intro').classList.remove('hidden');$('#intro').classList.add('playing');video.currentTime=0;video.play().catch(endIntro)};addEventListener('keydown',e=>{if(e.key==='Escape'){$('#detail').classList.add('hidden');if(!$('#intro').classList.contains('hidden'))endIntro()}});render();

